"use strict";
const fmt=(v,d=2)=>Number(v).toFixed(d);
const svg=(label,body)=>`<svg class="chart" viewBox="0 0 480 270" role="img" aria-label="${label}">${body}</svg>`;
const txt=(x,y,s,anchor="middle",fill="#516574")=>`<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${fill}" font-family="system-ui,sans-serif" font-size="11">${s}</text>`;
function bars(values,cumulative=false){let b="";for(let t=0;t<=100;t+=25){const y=220-t*1.8;b+=`<path d="M42 ${y}H468" stroke="#e1e7eb"/>`+txt(35,y+4,t,"end");}let sum=0,pts=[];values.forEach((v,i)=>{const x=49+i*41;b+=`<rect x="${x}" y="${220-v*1.8}" width="25" height="${v*1.8}" rx="2" fill="#245b78"><title>PC${i+1}: ${fmt(v)}%</title></rect>`+txt(x+12,239,i+1);sum+=v;pts.push([x+12,220-sum*1.8]);});if(cumulative){b+=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#b65b28" stroke-width="2"/>`;pts.forEach(p=>b+=`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#b65b28"/>`);}b+=txt(246,261,"Principal component")+txt(44,20,"Variance (%)","start");return svg(cumulative?"Scree plot with cumulative explained variance":"Percentage contribution to portfolio variance",b);}
function heat(data,names,labels){return `<table class="heat"><thead><tr><th scope="col">Stock</th>${labels.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${data.map((row,i)=>`<tr><th scope="row">${names[i]}</th>${row.map(v=>`<td style="background:${v>=0?`rgba(36,91,120,${Math.abs(v)*.86})`:`rgba(182,91,40,${Math.abs(v)*.86})`};color:${Math.abs(v)>.6?'white':'#17354b'}">${fmt(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function lossChart(p){const a=p.loss_pct,min=Math.min(...a,0),max=Math.max(...a,p.historical_var95_pct),span=max-min||1;const y=v=>220-(v-min)/span*180;let b='';[min,0,max].forEach(v=>{b+=`<path d="M42 ${y(v)}H465" stroke="#e1e7eb"/>`+txt(35,y(v)+4,fmt(v,1),'end');});const points=a.map((v,i)=>`${45+i/(a.length-1)*414},${y(v)}`).join(' ');b+=`<polyline points="${points}" fill="none" stroke="#245b78" stroke-width="1.1"/><path d="M42 ${y(p.historical_var95_pct)}H465" stroke="#b65b28" stroke-width="2" stroke-dasharray="5 4"/>`;b+=txt(44,20,'Daily loss (%)','start')+txt(45,243,p.start,'start')+txt(459,243,p.end,'end')+txt(245,263,'Observation date');return svg('Observed daily portfolio losses; dashed line marks historical 95% Value at Risk',b);}
function render(){const all=window.RESULTS;if(!all){document.getElementById('metrics').innerHTML='<p class="error">Saved results are missing. Keep results.js in the same folder as index.html.</p>';return;}const p=all.periods[document.getElementById('period').value];document.getElementById('period-note').textContent=`${p.n} daily return observations · ${p.start} to ${p.end}. Each stock has a 10% portfolio weight.`;
const cards=[['Daily volatility',fmt(p.daily_volatility_pct)+'%','Based on portfolio log-return variance'],['Historical 95% VaR',fmt(p.historical_var95_pct)+'%','One-day loss threshold'],['PC1 portfolio risk',fmt(p.portfolio_risk_pct[0],1)+'%','Share of this portfolio’s variance'],['Average correlation',fmt(p.mean_correlation),'Across 45 stock pairs']];
document.getElementById('metrics').innerHTML=cards.map(c=>`<div class="metric"><span>${c[0]}</span><strong>${c[1]}</strong><small>${c[2]}</small></div>`).join('');document.getElementById('scree').innerHTML=bars(p.explained_pct,true);document.getElementById('risk').innerHTML=bars(p.portfolio_risk_pct);document.getElementById('risk-note').textContent=`PC1 explains ${fmt(p.explained_pct[0],1)}% of variation across stocks, but ${fmt(p.portfolio_risk_pct[0],1)}% of this portfolio’s variance. These are different quantities.`;document.getElementById('loadings').innerHTML=heat(p.loadings.map(r=>r.slice(0,3)),p.tickers,['PC1','PC2','PC3']);document.getElementById('loss').innerHTML=lossChart(p);document.getElementById('var-note').textContent=`The dashed line is ${fmt(p.historical_var95_pct)}%. For an illustrative ₹100,000 portfolio, this is about ₹${Math.round(p.historical_var95_pct*1000).toLocaleString('en-IN')}. Losses can exceed it. Only ${p.n} observations underpin this estimate.`;
const cols=[['n','Days',0],['daily_volatility_pct','Volatility %',2],['historical_var95_pct','95% VaR %',2],['mean_correlation','Mean correlation',2],['benchmark_period_return_pct','NIFTY return %',2]];document.getElementById('comparison').innerHTML=`<table><thead><tr><th>Period</th>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${['comparison','stress'].map(k=>`<tr><th scope="row">${all.periods[k].label}</th>${cols.map(c=>`<td>${fmt(all.periods[k][c[0]],c[2])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const c=all.periods.comparison,s=all.periods.stress;document.getElementById('comparison-note').textContent=`In October–December 2024, the NIFTY 50 returned ${fmt(s.benchmark_period_return_pct)}%. Portfolio volatility was ${s.daily_volatility_pct>c.daily_volatility_pct?'higher':'lower'} than in July–September. A falling market does not automatically imply greater daily volatility.`;
const m=all.mardia,f=all.factor_analysis,full=all.periods.full,pv=v=>v<.001?'less than 0.001':fmt(v,4);document.getElementById('diagnostics').innerHTML=`<h3>Full study normality diagnostic</h3><p>Mardia skewness χ²(${m.skew_df}) = ${fmt(m.skew_chi2)}; p ${m.skew_p<.001?'':'='} ${pv(m.skew_p)}. Kurtosis z = ${fmt(m.kurt_z)}; p ${m.kurt_p<.001?'':'='} ${pv(m.kurt_p)}. ${m.reject_at_5pct_bonferroni?'Joint normality is rejected':'Joint normality is not rejected'} using 0.025 for each of the two tests. Daily observations may be dependent, so these p-values are diagnostics rather than exact time-series inference.</p><h3>Exploratory factor analysis</h3><p>Three rotated factors account for ${fmt(f.shared_share_pct,1)}% of the fitted portfolio variance; stock-specific noise accounts for ${fmt(f.specific_share_pct,1)}%. This fitted split is different from the exact PCA decomposition. Standardised covariance reconstruction RMSE: ${fmt(f.covariance_rmse_standardised,3)}.</p>${heat(f.loadings_standardised,full.tickers,['Factor 1','Factor 2','Factor 3'])}<h3>Generalised variance and conditional covariance</h3><p>Full study log determinant of the covariance matrix: ${fmt(full.log_generalised_variance)} (natural log, decimal return units). This measures joint spread across assets; portfolio variance additionally depends on weights.</p><p>After linearly accounting for the NIFTY 50, the equal-weight residual daily volatility is ${fmt(100*Math.sqrt(full.residual_portfolio_variance))}%. The market-associated linear share is ${fmt(full.market_linear_variance_share_pct,1)}%. With non-normal data, this is a regression residual covariance; an exact normal conditional-distribution interpretation is not claimed.</p>`;
}
document.getElementById('period').addEventListener('change',render);render();
